ad": "The forces that make California''s land, and what happens when we fight them."}, {"id": "industry", "name": "Boom & Bust", "thread": "Power plants, mines, mills and the towns they left behind."}, {"id": "coast", "name": "The Coast That Won''t Hold", "thread": "A coastline that keeps beating roads, buildings and industry."}, {"id": "redwoods", "name": "The Redwoods", "thread": "A mini-doc on the coast redwood biome, built from every coastal trip."}, {"id": "monterey", "name": "Monterey Bay Comeback", "thread": "Lost industries replaced by fragile recoveries."}, {"id": "curious", "name": "Strange California", "thread": "Folklore, oddities and the real stories underneath them."}], "stageWeeks": 1, "team": [{"does": "Leads research, co-writes, runs pre-production and camera, records the voice-over, and does the fine cut and finishing. Appears on camera in non-speaking moments.", "id": "producer", "name": "Producer", "share": "About 70%"}, {"does": "Co-writes and owns her on-camera lines. The only voice on camera. Assistant editor: sets up the Resolve project, ingests and syncs footage, and cuts the first pass.", "id": "host", "name": "Host", "share": "About 30%"}]}'::jsonb)
